# aplicar-cambios-franquicias-roles.ps1
#
# Aplica el cambio solicitado:
#   a) El modulo de Franquicias (dashboard, listado, Clubes) ahora solo lo pueden ver/usar
#      los roles: juridico, cabeza_juridico, ceo, cfo, y super_admin como respaldo total de
#      sistema (ya NO el rol generico "admin").
#   b) Un contrato de franquicia ya no pasa por el flujo de autorizacion: en cuanto se crea
#      (Nueva solicitud de franquicia, o el script de carga via PDF), queda de inmediato en
#      estatus 'activo' (club registrado), sin pasar por 'borrador' / 'en_autorizacion'.
#   c) Nuevo endpoint POST /contratos/:id/registrar-club-franquicia para empujar a 'activo' un
#      contrato de franquicia que se haya quedado en 'borrador' de ANTES de este cambio (por
#      ejemplo, el de Centro Santa Fe que ya tenias cargado) -- ver registrar-club-santa-fe.ps1.
#
# Este script sobreescribe 6 archivos con su version final (metodo Base64 -> bytes, el mismo
# que ya hemos usado en esta sesion para evitar problemas de encoding con acentos) y despues
# hace git add + commit + push.
#
# USO: parado dentro de tu copia local del repo (o ajusta $repoRoot abajo), corre:
#   .\aplicar-cambios-franquicias-roles.ps1

$ErrorActionPreference = "Stop"

$repoRoot = (Get-Location).Path
if (-not (Test-Path (Join-Path $repoRoot "backend")) -or -not (Test-Path (Join-Path $repoRoot "frontend"))) {
    Write-Host "No encuentro las carpetas 'backend' y 'frontend' en: $repoRoot" -ForegroundColor Red
    Write-Host "Corre este script parado en la raiz de tu copia local del repo fpt-contratos." -ForegroundColor Red
    exit 1
}

function Write-ArchivoBase64([string]$rutaRelativa, [string]$base64) {
    $rutaCompleta = Join-Path $repoRoot $rutaRelativa
    $bytes = [System.Convert]::FromBase64String($base64)
    [System.IO.File]::WriteAllBytes($rutaCompleta, $bytes)
    Write-Host "Escrito: $rutaRelativa"
}

Write-ArchivoBase64 "backend/src/utils/roles.js" ""
Write-ArchivoBase64 "backend/src/routes/franquicias.js" ""
Write-ArchivoBase64 "backend/src/routes/clubes.js" ""
Write-ArchivoBase64 "backend/src/routes/contratos.js" ""
Write-ArchivoBase64 "frontend/src/auth/AuthContext.jsx" ""
Write-ArchivoBase64 "frontend/src/pages/franquicias/NuevaSolicitudFranquicia.jsx" ""

Write-Host ""
Write-Host "Archivos escritos. Haciendo git add/commit/push..." -ForegroundColor Cyan

git add backend/src/utils/roles.js backend/src/routes/franquicias.js backend/src/routes/clubes.js backend/src/routes/contratos.js frontend/src/auth/AuthContext.jsx frontend/src/pages/franquicias/NuevaSolicitudFranquicia.jsx

git commit -m "Restringir modulo de Franquicias a Juridico/Cabeza de Juridico/CEO/CFO/super_admin, quitar flujo de autorizacion a contratos de franquicia y agregar endpoint de registro manual"

git push origin main

Write-Host ""
Write-Host "Listo. Espera el redeploy en Render (unos minutos) y luego corre registrar-club-santa-fe.ps1 para corregir el contrato CT-2026-0005." -ForegroundColor Green